import numpy as np
from scipy.optimize import minimize_scalar
def H(w):
    c=np.cos(w*t); s=np.sin(w*t); e=np.exp(-v); lv=np.log(v)
    return np.column_stack([np.ones_like(t),c,s,t*c,t*s,v*c,v*s,t*v*c,t*v*s,t*v*v*c,t*v*v*s,x,v,v*v,e,e*s,e*c,t*e,t*e*s,t*e*c,t*lv,lv,x*c,x*s])
names=['1','c','s','tc','ts','vc','vs','tvc','tvs','tvvc','tvvs','x','v','vv','e','es','ec','te','tes','tec','tlv','lv','xc','xs']
def err(w,idx):
    A=H(w)[:,idx]; co=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    return np.mean((dv_dt-A@co)**2)/np.var(dv_dt)
w=minimize_scalar(lambda w: err(w,list(range(24))),bounds=(0.41,0.44),method='bounded',options={'xatol':1e-10}).x
idx=list(range(24))
while len(idx)>9:
    best=None
    for j in idx:
        if j==0: continue
        trial=[k for k in idx if k!=j]
        e_=err(w,trial)
        if best is None or e_<best[0]: best=(e_,j)
    idx.remove(best[1])
w2=minimize_scalar(lambda w: err(w,idx),bounds=(0.40,0.46),method='bounded',options={'xatol':1e-10}).x
A=H(w2)[:,idx]; co=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
print('w',w2,'nmse',err(w2,idx))
for j,cc in zip(idx,co): print(names[j],round(cc,5))

